    def _print_MatPow(self, expr):
        "Matrix power printer"
        return '{0}({1}, {2})'.format(self._module_format('numpy.linalg.matrix_power'),
            self._print(expr.args[0]), self._print(expr.args[1]))

    def _print_Inverse(self, expr):
