def test_numpy_identity():
    if not numpy:
        skip("numpy not installed.")
    from sympy.matrices.expressions import Identity

    A = MatrixSymbol('A', 2, 2)
    a = numpy.array([[1, 2], [3, 4]])
    modules = [None, 'numpy']
    if scipy:
        modules.append('scipy')
    for module in modules:
        f = lambdify(A, A + Identity(2), modules=module)
        numpy.testing.assert_array_equal(f(a), [[2, 2], [3, 5]])
        f = lambdify([], Identity(2), modules=module)
        numpy.testing.assert_array_equal(f(), numpy.eye(2))


